n=np.array([50,100,250,500]);k=5;direct=n*(n+1)/2;factor=n*k+k*(k+1)/2+n;ax.plot(n,direct,color=BAD,marker='o',label='sample covariance');ax.plot(n,factor,color=ACCENT,marker='o',label='five-factor structure');ax.set_yscale('log');ax.set_xlabel('number of stocks');ax.set_ylabel('parameters (log scale)');ax.legend(fontsize=8);ax.set_title('Structure trades flexibility for estimability',loc='left')
